/**
 * The standalone copies of the shared look.
 *
 * Pages that cannot be served by the backend (the desktop app's screens, the
 * extension popup, the launcher and older pages) load their own copy of
 * ambient.css and ambient.js. Those copies are generated by
 * scripts/sync-ambient.mjs from interface/ambient.ts. This fails if one has
 * drifted, so there is never a page quietly on an older look.
 */

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { AMBIENT_CSS, AMBIENT_JS } from '../../interface/ambient.js'

const COPIES = ['desktop-app/src/renderer', 'browser-extension', 'interface/static']
const read = (file: string) => readFileSync(path.resolve(__dirname, '../..', file), 'utf8')

describe('standalone copies of the ambient look', () => {
  for (const dir of COPIES) {
    it(`${dir} matches the source (run: node scripts/sync-ambient.mjs)`, () => {
      expect(read(`${dir}/ambient.css`)).toBe(AMBIENT_CSS)
      expect(read(`${dir}/ambient.js`)).toBe(AMBIENT_JS)
    })
  }
})
